// Generated by Suite Builder from a crawl of the site. The waits every page uses to decide it has loaded.
// EDIT RULES: edit only inside YOURS blocks; regenerating keeps them and rewrites the rest of this file.
import { Find, shownIn } from './Find';
import type { PageElement } from './PageElement';
import { SiteConfig } from './SiteConfig';

/** Lists what a page is still loading (the same script in every framework); whether the last load event was in time. */
const STILL_LOADING = '(function () {\n  var out = [];\n  var frames = document.querySelectorAll("iframe");\n  for (var i = 0; i < frames.length; i++) {\n    var f = frames[i], doc = null, state;\n    try { doc = f.contentDocument; } catch (e) { doc = null; }\n    if (!doc) state = "another site";\n    else if (f.src && f.src !== "about:blank" && doc.URL === "about:blank") state = "loading";\n    else state = doc.readyState;\n    if (state !== "complete") out.push("frame " + (f.src || "(no address)") + (state === "another site" ? " (another site\'s frame: a suspect)" : " (" + state + ")"));\n  }\n  var media = document.querySelectorAll("video, audio");\n  for (var j = 0; j < media.length; j++) {\n    var m = media[j], source = m.querySelector("source");\n    if (m.networkState === 2 && m.readyState < 2) out.push(m.tagName.toLowerCase() + " " + (m.currentSrc || m.src || (source && source.src) || "(no address)"));\n  }\n  for (var k = 0; k < document.images.length; k++) {\n    var img = document.images[k];\n    if (!img.complete) out.push("image " + (img.currentSrc || img.src));\n  }\n  return out.slice(0, 10);\n})()';
let loadedInTime = true;

/**
 * The waits every page's isLoaded() is built from. Each is a Cypress command that retries until it
 * holds, and otherwise fails with the sentence it was given, so isLoaded() says exactly what was
 * not ready. URLs and titles are compared as plain strings.
 *
 * Timeouts, from cypress.config.ts: pageLoadTimeout (30000 ms) for a page and
 * everything it loads; defaultCommandTimeout (10000 ms) for URLs, titles and elements.
 */
export const WaitActions = {
  pageLoadTimeout: (): number => Cypress.config('pageLoadTimeout'),
  elementTimeout: (): number => Cypress.config('defaultCommandTimeout'),

  /** The browser is on exactly this path of the site (query and #fragment aside). */
  forUrl(path: string, failure: (url: string) => string): void {
    const expected = SiteConfig.url(path);
    cy.location('href', { log: false }).should((href) => {
      if (!WaitActions.samePage(href, expected)) throw new Error(failure(href));
    });
  },

  /** A URL of one of these shapes, e.g. "/blog/*": "*" is one path segment, "{n}" a number. */
  forUrlShape(shapes: readonly string[], failure: (url: string) => string): void {
    cy.location('href', { log: false }).should((href) => {
      if (!WaitActions.fitsShapes(href, shapes)) throw new Error(failure(href));
    });
  },

  /** Waits up to pageLoadTimeout for the load event without failing; noteIfStillLoading() names a late one. (cy.visit() still fails on it: Cypress's rule.) */
  forPageLoad(): void {
    cy.document({ log: false }).then({ timeout: WaitActions.pageLoadTimeout() + 1000 }, (doc) =>
      new Cypress.Promise<boolean>((resolve) => {
        if (doc.readyState === 'complete') return resolve(true);
        const timer = setTimeout(() => resolve(doc.readyState === 'complete'), WaitActions.pageLoadTimeout());
        doc.defaultView?.addEventListener('load', () => { clearTimeout(timer); resolve(true); }, { once: true });
      }).then((loaded) => (loadedInTime = loaded)));
  },

  /** After the page is proven: says so if its load event was late, and what it was still loading. */
  noteIfStillLoading(name: string): void {
    cy.window({ log: false }).then((win) => {
      if (loadedInTime) return;
      const parts = ((win as unknown as { eval(script: string): unknown }).eval(STILL_LOADING) as string[] | undefined) ?? [];
      const note = `   note: ${name} is the right page (address, title and checks hold), but had not finished loading after ${WaitActions.pageLoadTimeout() / 1000} s${parts.length ? `; still loading: ${parts.join(', ')}` : ''}`;
      return cy.task('suiteLog', note, { log: false });
    });
  },

  /** Exactly this title (runs of whitespace count as one space). */
  forTitle(title: string, failure: (actual: string) => string): void {
    cy.title({ log: false }).should((actual) => {
      if (!WaitActions.sameText(actual, title)) throw new Error(failure(actual));
    });
  },

  /** A title that starts and ends like this (the page's own name goes in between). */
  forTitleShape(startsWith: string, endsWith: string, failure: (actual: string) => string): void {
    cy.title({ log: false }).should((actual) => {
      if (!WaitActions.titleFits(actual, startsWith, endsWith)) throw new Error(failure(actual));
    });
  },

  /** The element is visible (within timeoutMs, if given). */
  forVisibilityOf(element: PageElement, failure: string, timeoutMs?: number): void {
    cy.document({ log: false, timeout: timeoutMs }).should((doc) => {
      if (!shownIn(doc, element, true).length) throw new Error(failure);
    });
  },

  /** The element is gone or hidden: a spinner, an overlay, a "Loading..." message. */
  forInvisibilityOf(element: PageElement, failure: string): void {
    cy.document({ log: false }).should((doc) => {
      if (shownIn(doc, element).length) throw new Error(failure);
    });
  },

  /** True now (no waiting) when the element is visible. */
  isVisibleNow(element: PageElement): boolean {
    return Find.isVisibleNow(element);
  },

  // ---- Plain string checks (no browser needed) -------------------------------------------

  /** True when both URLs are the same page: same site and path; query, #fragment and a final "/" aside. */
  samePage(url: string, expectedUrl: string): boolean {
    return pageOf(url) === pageOf(expectedUrl);
  },

  /** True when the URL's path has one of these shapes. */
  fitsShapes(url: string, shapes: readonly string[]): boolean {
    return shapes.some((shape) => WaitActions.fitsShape(url, shape));
  },

  /** True when the URL's path has this shape: "*" is any one segment, "{n}" a number. */
  fitsShape(url: string, shape: string): boolean {
    const actual = segments(pathOf(url));
    const wanted = segments(shape);
    if (actual.length !== wanted.length) return false;
    return wanted.every((w, i) => w === '*' || (w === '{n}' ? isNumber(actual[i]) : w === actual[i]));
  },

  /** True when both say the same, whatever the spacing: runs of whitespace count as one space. */
  sameText(text: string | null | undefined, expected: string): boolean {
    return spaces(text).trim() === spaces(expected).trim();
  },

  /** True when the text contains the expected words, whatever the spacing. */
  containsText(text: string | null | undefined, expected: string): boolean {
    return spaces(text).includes(spaces(expected).trim());
  },

  titleFits(title: string, startsWith: string, endsWith: string): boolean {
    const t = spaces(title).trim();
    const start = spaces(startsWith);
    const end = spaces(endsWith);
    return t.length > start.length + end.length && t.startsWith(start) && t.endsWith(end);
  },

  // ==== YOURS (extras): safe to edit; regenerating keeps what is between these lines ====
  // More waits, e.g. for a third-party widget this site loads late. Add them here, not in a page.
  // ==== END YOURS (extras) ====
};

/** "https://Example.com/a/b/?q=1#x" -> "https://example.com/a/b" */
function pageOf(url: string): string {
  const schemeEnd = url.indexOf('://');
  const pathStart = schemeEnd < 0 ? 0 : url.indexOf('/', schemeEnd + 3);
  const origin = pathStart < 0 ? url : url.slice(0, pathStart);
  return origin.toLowerCase() + trimSlash(pathOf(url));
}

/** The path of a URL (or of a path), decoded: no scheme, host, query or #fragment; %20 is a space. */
function pathOf(url: string): string {
  let rest = url;
  const schemeEnd = rest.indexOf('://');
  if (schemeEnd >= 0) {
    const pathStart = rest.indexOf('/', schemeEnd + 3);
    rest = pathStart < 0 ? '/' : rest.slice(pathStart);
  }
  for (const stop of ['?', '#']) {
    const at = rest.indexOf(stop);
    if (at >= 0) rest = rest.slice(0, at);
  }
  try {
    return decodeURIComponent(rest || '/');
  } catch {
    return rest || '/'; // not valid percent-encoding: as written
  }
}

function trimSlash(path: string): string {
  return path.length > 1 && path.endsWith('/') ? path.slice(0, -1) : path;
}

function segments(path: string): string[] {
  const p = trimSlash(pathOf(path));
  return p === '/' ? [] : p.slice(1).split('/');
}

function isNumber(s: string): boolean {
  return s.length > 0 && [...s].every((c) => c >= '0' && c <= '9');
}

/** Every run of whitespace (non-breaking spaces too) as one space. */
function spaces(s: string | null | undefined): string {
  let out = '';
  let inSpace = false;
  for (const c of s ?? '') {
    if (c.trim() === '') {
      if (!inSpace) out += ' ';
      inSpace = true;
    } else {
      out += c;
      inSpace = false;
    }
  }
  return out;
}
